use Civi\Lughauth\Features\Document\SnippetAsset\Domain\ValueObject\Accessor\SnippetAssetTypeAccessor;
use Civi\Lughauth\Features\Document\SnippetAsset\Domain\ValueObject\SnippetAssetContentVO;
use Civi\Lughauth\Features\Document\SnippetAsset\Domain\ValueObject\Accessor\SnippetAssetContentAccessor;
use Civi\Lughauth\Features\Document\SnippetAsset\Domain\ValueObject\SnippetAssetEnabledVO;
use Civi\Lughauth\Features\Document\SnippetAsset\Domain\ValueObject\Accessor\SnippetAssetEnabledAccessor;
use Civi\Lughauth\Features\Document\SnippetAsset\Domain\ValueObject\SnippetAssetVersionVO;
use Civi\Lughauth\Features\Document\SnippetAsset\Domain\ValueObject\Accessor\SnippetAssetVersionAccessor;
use Civi\Lughauth\Features\Document\SnippetAsset\Domain\Formula\EnabledCalculator;
use Civi\Lughauth\Features\Document\SnippetAsset\Domain\Event\SnippetAssetCreateEvent;
use Civi\Lughauth\Features\Document\SnippetAsset\Domain\Event\SnippetAssetUpdateEvent;
use Civi\Lughauth\Features\Document\SnippetAsset\Domain\Event\SnippetAssetDeleteEvent;
use Civi\Lughauth\Features\Document\SnippetAsset\Domain\Event\SnippetAssetEnableEvent;
use Civi\Lughauth\Features\Document\SnippetAsset\Domain\Event\SnippetAssetDisableEvent;
use Civi\Lughauth\Features\Document\Snippet\Domain\SnippetRef;
use Civi\Lughauth\Shared\Connector\FileStorage\FileStorageInterface;
use Civi\Lughauth\Shared\Connector\FileStorage\FileStoreKey;

class SnippetAsset extends SnippetAssetRef
{
    use SnippetAssetSnippetAccessor;
    use SnippetAssetCodeAccessor;
    use SnippetAssetTypeAccessor;
    use SnippetAssetContentAccessor;
    use SnippetAssetEnabledAccessor;
    use SnippetAssetVersionAccessor;
    private array $recordedEvents = [];

    public function __construct(
        SnippetAssetUidVO|string $uid,
        SnippetAssetSnippetVO|SnippetRef $snippet,
        SnippetAssetCodeVO|string $code,
        SnippetAssetTypeVO|string $type,
        SnippetAssetContentVO|string $content,
        SnippetAssetEnabledVO|bool|null $enabled = null,
        SnippetAssetVersionVO|int|null $version = null,
    ) {
        parent::__construct($uid);
        $this->_snippet = SnippetAssetSnippetVO::from($snippet);
        $this->_code = SnippetAssetCodeVO::from($code);
        $this->_type = SnippetAssetTypeVO::from($type);
        $this->_content = SnippetAssetContentVO::from($content);
        $this->_enabled = null === $enabled ? SnippetAssetEnabledVO::empty() : SnippetAssetEnabledVO::from($enabled);
        $this->_version = null === $version ? SnippetAssetVersionVO::empty() : SnippetAssetVersionVO::from($version);
    }
    public function replace(SnippetAssetAttributes $values): SnippetAsset
    {
        $value = clone $this;
        $value->_snippet = $values->getSnippetOrCurrent($this->_snippet);
        $value->_code = $values->getCodeOrCurrent($this->_code);
        $value->_type = $values->getTypeOrCurrent($this->_type);
        $value->_content = $values->getContentOrCurrent($this->_content);
        $value->_enabled = $values->getEnabledOrCurrent($this->_enabled);
        $value->_version = $values->getVersionOrCurrent($this->_version);
        return $value;
    }
    public static function calculatedFields(): array
    {
        return [ 'enabled'];
    }
    public static function create(SnippetAssetAttributes $values): SnippetAsset
    {
        $calculated = clone $values;
        $calculated->enabled(EnabledCalculator::calculateEnabled());
        $value = $calculated->createNewInstance();
        $value->recordedEvents[] = new SnippetAssetCreateEvent($value);
        return $value;
    }
    public function update(SnippetAssetAttributes $values): SnippetAsset
    {
        $calculated = clone $values;
        $calculated->enabled(EnabledCalculator::calculateEnabled($this));
        $value = $this->replace($calculated);
        $value->recordedEvents[] = new SnippetAssetUpdateEvent($value, $this);
        return $value;
    }
    public function delete(): SnippetAsset
    {
        $value = clone $this;
        $value->recordedEvents[] = new SnippetAssetDeleteEvent($value);
        return $value;
    }
    public function commitContentWith(FileStorageInterface $store): void
    {
        $key = $store->commitContent(new FileStoreKey($this->getContent()));
        $this->_content = SnippetAssetContentVO::fromStored($key->key);
    }
    public function enable(): SnippetAsset
    {
        $value = clone $this;
        $value->_enabled = SnippetAssetEnabledVO::from(true);
        $value->recordedEvents[] = new SnippetAssetEnableEvent($value, original: $this);
        return $value;
    }
    public function disable(): SnippetAsset
    {
        $value = clone $this;
        $value->_enabled = SnippetAssetEnabledVO::from(false);
        $value->recordedEvents[] = new SnippetAssetDisableEvent($value, original: $this);
        return $value;
    }
    public function asPublicJson(): array
    {
        $data = [];
        $data['uid'] = $this->uid();
        $data['snippet'] = [ '$ref' => $this->getSnippet()->uid() ];
        $data['code'] = $this->getCode();
        $data['type'] = $this->getType();
        $data['enabled'] = $this->isEnabled();
        $data['version'] = $this->getVersion();
        return $data;
    }
    public function toAttributes(): SnippetAssetAttributes
    {
        return (new SnippetAssetAttributes())
          ->uid($this->uid())
          ->snippet($this->_snippet)
          ->code($this->_code)
          ->type($this->_type)
          ->content($this->_content)
          ->enabled($this->_enabled)
          ->version($this->_version);
    }
    public function getTheEvents(): array
    {
        return [...$this->recordedEvents];
    }
}
